<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/nursing_requests.php';requireLogin();nrSchema($conn);$actor=exActor($conn,(int)$_SESSION['user_id']);if(naRole($actor)!=='SUPER_ADMIN'){http_response_code(403);exit('Administrator access required.');}$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrfToken();try{$action=$_POST['action']??'';$conn->begin_transaction();nsScheduleQuery($conn,'SELECT id FROM nursing_exchange_mutex WHERE id=1 FOR UPDATE');$before=[];
if($action==='hierarchy'){$employee=exActor($conn,(int)$_POST['employee']);$approver=exActor($conn,(int)$_POST['approver']);$role=naRole($approver);if(!naEligible($employee)||!in_array($role,['HEAD_NURSE','SUPERVISOR_NURSE','ASSISTANT_CHIEF_NURSE','CHIEF_NURSE'],true)||(int)$employee['user_id']===(int)$approver['user_id'])throw new DomainException('Select a nursing employee and an independent approver with a superior role.');$before=exRows($conn,'SELECT * FROM nursing_reporting_hierarchy WHERE employee_id=? AND approver_role=?',[$employee['user_id'],$role]);nsScheduleQuery($conn,'UPDATE nursing_reporting_hierarchy SET enabled=0 WHERE employee_id=? AND approver_role=?',[$employee['user_id'],$role]);nsScheduleQuery($conn,'INSERT INTO nursing_reporting_hierarchy(employee_id,approver_role,approver_id,enabled) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE enabled=1',[$employee['user_id'],$role,$approver['user_id']]);foreach(exRows($conn,"SELECT * FROM nursing_service_requests WHERE employee_id=? AND status='PENDING_APPROVAL'",[$employee['user_id']]) as $pending){$route=json_decode($pending['route_json'],true);if(($route[$pending['stage']]['role']??'')===$role)nrNotify($conn,$pending);}}
elseif($action==='employee'){$employee=exActor($conn,(int)$_POST['employee']);if(!naEligible($employee)||!in_array($_POST['fixed_shift'],['6','7','8','M'],true))throw new DomainException('Invalid nursing employee or fixed shift.');$eligibility=preg_split('/[\s,]+/',trim($_POST['eligibility']??''),-1,PREG_SPLIT_NO_EMPTY);foreach($eligibility as $code)if(!array_key_exists($code,nsScheduleDuties()))throw new InvalidArgumentException('Unknown eligible shift.');$before=exRows($conn,'SELECT * FROM nursing_schedule_employee_policy WHERE employee_id=?',[$employee['user_id']]);nsScheduleQuery($conn,'INSERT INTO nursing_schedule_employee_policy(employee_id,scheduling_active,fixed_shift,shift_eligibility) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE scheduling_active=VALUES(scheduling_active),fixed_shift=VALUES(fixed_shift),shift_eligibility=VALUES(shift_eligibility)',[$employee['user_id'],isset($_POST['active'])?1:0,$_POST['fixed_shift'],nsScheduleEncode($eligibility)]);}
elseif($action==='shift'){$code=$_POST['code']??'';$old=exOne($conn,'SELECT * FROM nursing_shift_master WHERE code=?',[$code]);if(!$old)throw new InvalidArgumentException('Select an existing shift.');$before=$old;$start=filter_var($_POST['start'],FILTER_VALIDATE_FLOAT);$elapsed=filter_var($_POST['elapsed'],FILTER_VALIDATE_FLOAT);$meal=filter_var($_POST['meal'],FILTER_VALIDATE_FLOAT);$credit=filter_var($_POST['credit'],FILTER_VALIDATE_FLOAT);if(in_array(false,[$start,$elapsed,$meal,$credit],true)||$start<0||$start>=24||$elapsed<0||$elapsed>24||$meal<0||$meal>$elapsed||$credit<0||$credit>$elapsed)throw new InvalidArgumentException('Invalid shift hours.');$unit=trim($_POST['shift_department']??'');if($unit!==''){$unit=canonicalDepartment($unit);if(!isset(nsScheduleDepartments()[$unit]))throw new InvalidArgumentException('Choose a supported shift department.');$before=exOne($conn,'SELECT * FROM nursing_department_shifts WHERE department=? AND code=?',[$unit,$code]);nsScheduleQuery($conn,'INSERT INTO nursing_department_shifts(department,code,label,start_hour,elapsed_hours,meal_hours,credited_hours,cross_midnight) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE start_hour=VALUES(start_hour),elapsed_hours=VALUES(elapsed_hours),meal_hours=VALUES(meal_hours),credited_hours=VALUES(credited_hours),cross_midnight=VALUES(cross_midnight)',[$unit,$code,$old['label'],$start,$elapsed,$meal,$credit,$start+$elapsed>=24?1:0]);}else nsScheduleQuery($conn,'UPDATE nursing_shift_master SET start_hour=?,elapsed_hours=?,meal_hours=?,credited_hours=?,cross_midnight=? WHERE code=?',[$start,$elapsed,$meal,$credit,$start+$elapsed>=24?1:0,$code]);}
elseif($action==='department'){$dept=canonicalDepartment($_POST['department']);if(!isset(nsScheduleDepartments()[$dept]))throw new InvalidArgumentException('Choose a supported department.');$mode=$_POST['mode'];if(!in_array($mode,['FIXED','ROTATING'],true))throw new InvalidArgumentException('Invalid mode.');$target=filter_var($_POST['target'],FILTER_VALIDATE_FLOAT);if($target===false||$target<0||$target>744)throw new InvalidArgumentException('Invalid target.');$days=$_POST['days']??[];if(!$days||array_diff($days,['0','1','2','3','4','5','6']))throw new InvalidArgumentException('Choose operating days.');$shifts=preg_split('/[\s,]+/',trim($_POST['shifts']??''),-1,PREG_SPLIT_NO_EMPTY);foreach($shifts as $code)if(!(nsScheduleDuties()[$code]??0))throw new InvalidArgumentException('Choose working shift codes.');$before=nsPolicy($conn,$dept);nsScheduleQuery($conn,'INSERT INTO nursing_schedule_policy(department,mode,target_hours,operating_days,required_shifts,updated_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE mode=VALUES(mode),target_hours=VALUES(target_hours),operating_days=VALUES(operating_days),required_shifts=VALUES(required_shifts),updated_by=VALUES(updated_by)',[$dept,$mode,$target,implode(',',$days),nsScheduleEncode($shifts),$actor['user_id']]);}
elseif($action==='holiday'){$date=exDate($_POST['date']);$label=trim($_POST['label']);if(!$label||strlen($label)>160)throw new InvalidArgumentException('Enter a holiday label.');$before=exRows($conn,'SELECT * FROM nursing_schedule_holidays WHERE holiday_date=?',[$date]);nsScheduleQuery($conn,'INSERT INTO nursing_schedule_holidays VALUES(?,?,?) ON DUPLICATE KEY UPDATE label=VALUES(label),updated_by=VALUES(updated_by)',[$date,$label,$actor['user_id']]);}
elseif($action==='leave'){$code=$_POST['code'];$before=exOne($conn,'SELECT * FROM nursing_leave_policy WHERE code=?',[$code]);if(!$before)throw new InvalidArgumentException('Invalid leave type.');$max=trim($_POST['max_days']??'');if($max!==''&&(!ctype_digit($max)||(int)$max<1||(int)$max>366))throw new InvalidArgumentException('Invalid duration limit.');$credit=filter_var($_POST['leave_credit']??0,FILTER_VALIDATE_FLOAT);if($credit===false||$credit<0||$credit>24)throw new InvalidArgumentException('Invalid leave credit hours.');$roles=preg_split('/[\s,]+/',trim($_POST['roles']??''),-1,PREG_SPLIT_NO_EMPTY);if(array_diff($roles,['NURSING_ATTENDANT','STAFF_NURSE','HEAD_NURSE','SUPERVISOR_NURSE','ASSISTANT_CHIEF_NURSE','CHIEF_NURSE']))throw new InvalidArgumentException('Unknown nursing role.');nsScheduleQuery($conn,'UPDATE nursing_leave_policy SET enabled=?,max_days=?,required_document=?,eligible_roles=?,credited_hours=? WHERE code=?',[isset($_POST['enabled'])?1:0,$max===''?null:$max,isset($_POST['required_document'])?1:0,nsScheduleEncode($roles),$credit,$code]);}
else throw new InvalidArgumentException('Invalid setting.');$audit=$_POST;unset($audit['csrf_token']);nsScheduleQuery($conn,'INSERT INTO nursing_schedule_policy_audit(actor_id,action,before_json,after_json) VALUES(?,?,?,?)',[$actor['user_id'],$action,nsScheduleEncode($before),nsScheduleEncode($audit)]);$conn->commit();$message='Configuration saved. Existing published snapshots remain intact.';
}catch(Throwable $e){$conn->rollback();$error=$e instanceof DomainException||$e instanceof InvalidArgumentException?$e->getMessage():'Unable to save configuration.';error_log($e->getMessage());}}
$employees=array_values(array_filter(exRows($conn,"SELECT * FROM users WHERE is_active=1 AND status='ACTIVE' ORDER BY last_name"),'naEligible'));
function ncEmployees(array $employees): void {foreach($employees as $e)echo '<option value="'.(int)$e['user_id'].'">'.h($e['first_name'].' '.$e['last_name'].' / '.naRole($e).' / '.$e['department']).'</option>';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scheduling Configuration | JVGH</title><link rel="stylesheet" href="../public/css/style.css"><link rel="stylesheet" href="../public/css/dashboard.css"><link rel="stylesheet" href="../public/css/module-theme.css?v=18"><link rel="stylesheet" href="../public/css/schedule-management.css"><link rel="stylesheet" href="../public/css/request-tracking.css?v=2"><script defer src="../public/js/sidebar.js"></script><script defer src="../public/js/nursync-ui.js?v=4"></script><script defer src="../public/js/schedule-sidebar.js?v=1"></script></head><body class="module-ui schedule-page request-tracking-page"><nav class="navbar"><div class="navbar-brand"><h1>NURSYNC</h1></div><div class="navbar-menu"><span class="user-info"><?=h($actor['name'])?></span></div></nav><div class="dashboard-container"><?php include __DIR__.'/../includes/schedule_sidebar.php';?><main class="main-content schedule-main"><h2>Scheduling configuration</h2><p role="status"><?=h($error?:$message)?></p>
<section class="rt-panel"><h3>Employee reporting hierarchy</h3><form method="post" class="schedule-form"><?=csrfField()?><input name="action" type="hidden" value="hierarchy"><label>Employee<select name="employee"><?php ncEmployees($employees);?></select></label><label>Reporting approver / formal delegate<select name="approver"><?php ncEmployees(array_values(array_filter($employees,fn($e)=>in_array(naRole($e),['HEAD_NURSE','SUPERVISOR_NURSE','ASSISTANT_CHIEF_NURSE','CHIEF_NURSE'],true))));?></select></label><footer><button class="btn btn-primary">Assign reporting approver</button></footer></form><div class="table-responsive"><table class="schedule-table"><thead><tr><th>Employee ID</th><th>Approver role</th><th>Approver ID</th></tr></thead><tbody><?php foreach(exRows($conn,'SELECT * FROM nursing_reporting_hierarchy WHERE enabled=1') as $r):?><tr><td><?=$r['employee_id']?></td><td><?=h($r['approver_role'])?></td><td><?=$r['approver_id']?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="rt-panel"><h3>Employee shift eligibility</h3><form method="post" class="schedule-form"><?=csrfField()?><input name="action" type="hidden" value="employee"><label>Employee<select name="employee"><?php ncEmployees($employees);?></select></label><label>Fixed shift<select name="fixed_shift"><?php foreach(['6','7','8','M'] as $c):?><option><?=$c?></option><?php endforeach;?></select></label><label>Eligible internal shift IDs (blank = department choices)<input name="eligibility" placeholder="AM, PM, NIGHT8, DAY12, NIGHT12, ADJUST8, PM8"></label><label><input type="checkbox" name="active" checked> Active for scheduling</label><footer><button class="btn btn-primary">Save employee policy</button></footer></form></section>
<section class="rt-panel"><h3>Department policy</h3><form method="post" class="schedule-form"><?=csrfField()?><input type="hidden" name="action" value="department"><label>Department<select name="department"><?php foreach(nsScheduleDepartments() as $code=>$label):?><option value="<?=h($code)?>"><?=h($label)?></option><?php endforeach;?></select></label><label>Mode<select name="mode"><option>ROTATING</option><option>FIXED</option></select></label><label>Target credited hours<input type="number" step=".25" min="0" max="744" name="target" value="160" required></label><label>Required operational shift IDs<input name="shifts" placeholder="AM, PM, NIGHT8"></label><fieldset class="full"><legend>Operating days (fixed units and OR)</legend><?php foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $n=>$day):?><label><input type="checkbox" name="days[]" value="<?=$n?>" <?=$n>0&&$n<6?'checked':''?>><?=$day?></label><?php endforeach;?></fieldset><footer><button class="btn btn-primary">Save department policy</button></footer></form><p>OR shift coverage must be configured from its actual operations. No staffing count is assumed. Clinical 12-hour patterns map AM / PM / N coverage to their two operational shifts.</p></section>
<section class="rt-panel"><h3>Shift Master</h3><p>Start is decimal hours after midnight. Meal deductions and credited hours are stored separately. Default daytime meal deduction is one hour; confirm it against hospital policy.</p><?php foreach(exRows($conn,'SELECT * FROM nursing_shift_master WHERE elapsed_hours>0') as $r):?><form method="post" class="schedule-form"><?=csrfField()?><input name="action" type="hidden" value="shift"><input name="code" type="hidden" value="<?=h($r['code'])?>"><strong><?=h($r['code'].' / '.$r['label'])?></strong><label>Shift scope<select name="shift_department"><option value="">Shared default</option><?php foreach(nsScheduleDepartments() as $dept=>$label):?><option value="<?=h($dept)?>"><?=h($label)?></option><?php endforeach;?></select></label><label>Start<input type="number" step=".25" name="start" value="<?=$r['start_hour']?>" required></label><label>Elapsed hours<input type="number" step=".25" name="elapsed" value="<?=$r['elapsed_hours']?>" required></label><label>Meal hours<input type="number" step=".25" name="meal" value="<?=$r['meal_hours']?>" required></label><label>Credited hours<input type="number" step=".25" name="credit" value="<?=$r['credited_hours']?>" required></label><button class="btn btn-light">Save shift</button></form><?php endforeach;?></section>
<section class="rt-panel"><h3>Holiday calendar</h3><form method="post" class="schedule-form"><?=csrfField()?><input name="action" type="hidden" value="holiday"><label>Date<input type="date" name="date" required></label><label>Designation<input name="label" maxlength="160" required></label><footer><button class="btn btn-primary">Save holiday</button></footer></form></section>
<section class="rt-panel"><h3>Leave policy</h3><p>Blank duration or roles means no configured cap or role restriction; it does not grant a statutory entitlement.</p><?php foreach(exRows($conn,'SELECT * FROM nursing_leave_policy') as $r):?><form method="post" class="schedule-form"><?=csrfField()?><input name="action" type="hidden" value="leave"><input name="code" type="hidden" value="<?=h($r['code'])?>"><strong><?=h($r['label'])?></strong><label>Maximum days<input type="number" name="max_days" value="<?=h($r['max_days'])?>" min="1" max="366"></label><label>Authorized credit hours per day<input type="number" step=".25" min="0" max="24" name="leave_credit" value="<?=h($r['credited_hours'])?>"></label><label>Eligible actual roles<input name="roles" value="<?=h(implode(', ',json_decode($r['eligible_roles']??'[]',true)??[]))?>"></label><label><input type="checkbox" name="enabled" <?=$r['enabled']?'checked':''?>> Enabled</label><label><input type="checkbox" name="required_document" <?=$r['required_document']?'checked':''?>> Supporting document required</label><button class="btn btn-light">Save policy</button></form><?php endforeach;?></section>
</main></div></body></html>
